    .intro { max-width:570px; margin:0 0 4px; font-size:clamp(18px,2vw,23px); line-height:1.44; }
    .eyebrow { display:flex; justify-content:space-between; gap:12px; border-top:1px solid var(--line); padding:9px 0; color:var(--clay); font-size:9px; }
    .reading-grid { display:grid; grid-template-columns:minmax(270px,.78fr) minmax(0,1.22fr); gap:clamp(24px,4vw,54px); align-items:start; }
    figure { margin:0; }
    .marked { position:relative; background:#d2d2d0; border:1px solid #a6a7a1; }
    .marked img { display:block; width:100%; height:auto; }
    .marked svg { position:absolute; inset:0; width:100%; height:100%; pointer-events:none; }
    .marked .figure-box { fill:none; stroke:var(--clay); stroke-width:3; vector-effect:non-scaling-stroke; }
    .marked .base-box { fill:none; stroke:var(--green); stroke-width:3; vector-effect:non-scaling-stroke; }
    .marked .letter { font:700 12px \"Courier New\",monospace; text-anchor:middle; dominant-baseline:middle; fill:var(--sheet); }
    .marked .badge-a { fill:var(--clay); }
    .marked .badge-b { fill:var(--green); }
    .legend { display:grid; grid-template-columns:1fr 1fr; gap:12px; margin-top:9px; color:var(--muted); font-size:9px; line-height:1.5; }
    .legend span::before { content:\"\"; display:inline-block; width:11px; height:11px; margin:0 7px -2px 0; border:2px solid currentColor; }
    .legend .a { color:var(--clay); }
    .legend .b { color:var(--green); }
    .legend .a span,.legend .b span { color:var(--muted); }
    .cards { display:grid; gap:18px; }
    .card { display:grid; grid-template-columns:92px 1fr; gap:17px; border-top:1px solid var(--ink); padding-top:11px; }
    .tag { font-size:9px; line-height:1.55; color:var(--muted); }
    .tag b { display:block; font-size:27px; font-weight:400; }
    .card.composition .tag b { color:var(--clay); }
    .card.base .tag b { color:var(--green); }
    h2 { margin:0 0 8px; font-size:clamp(27px,3.4vw,43px); line-height:1; font-weight:400; letter-spacing:-.04em; }
    .card p { max-width:600px; margin:0; font-size:15px; line-height:1.48; }
