    a { color:inherit; text-underline-offset:3px; }
    .conclusion { display:grid; grid-template-columns:.75fr 1.25fr; gap:30px; border-top:1px solid var(--ink); margin-top:31px; padding-top:12px; }
    .conclusion p { margin:0; font-size:clamp(18px,2vw,23px); line-height:1.43; }
    .conclusion .small { color:var(--muted); font-size:14px; }
