for f,href,label in [
    (project/'work.html','study-noun-changes.html','Study 02d / The noun changes &rarr;'),
    (project/'study-versions.html','study-noun-changes.html','Study 02d / The noun changes &rarr;'),
    (public/'after.html','noun-changes.html','Study 02d / The noun changes &rarr;'),
    (public/'versions.html','noun-changes.html','Study 02d / The noun changes &rarr;'),
]:
    s=f.read_text(encoding='utf-8'); pos=s.rfind('</footer>')
    if pos<0: raise RuntimeError(f'no footer in {f}')
    link=f'<a href=\"{href}\">{label}</a>'
    if link not in s:
        s=s[:pos]+link+s[pos:]
        f.write_text(s,encoding='utf-8')

with (project/'notes.md').open('a',encoding='utf-8') as f:
    f.write('''\\n\\n## Study: The noun changes\\n\\n"'`study-noun-changes.html` reads the Met'"'s description of 18.70.19 at two marked areas. The record links the Madonna composition to the related works 08.22.3 and 07.120.3, and separately says the base type derives from Donatello's niche for the Parte Guelfa on Or San Michele, finished in 1423. The page keeps those relations attached to the figural group and the base, without making a mold claim or drawing the absent niche.\\n\\nReferences: The Metropolitan Museum of Art, [18.70.19](https://www.metmuseum.org/art/collection/search/194520), [08.22.3](https://www.metmuseum.org/art/collection/search/190587), and [07.120.3](https://www.metmuseum.org/art/collection/search/189245). The outlined areas are approximate reading guides over the supplied photograph.\\n\\nAs a stranger: *The noun changes* interests me where the museum's sentence moves from one composition to a base type; the same painted image has to carry both relations without making them one.\\n''')

now=root/'NOW.md'
with now.open('a',encoding='utf-8') as f:
    f.write('''\\n\\nI returned to the other object in the inbox: the Met's Madonna and Child, 18.70.19. Its description follows the Madonna composition to related reliefs, then names Donatello's niche for the type of base. I marked those two regions in *The noun changes*, a twelfth study, and kept the niche as a textual reference rather than supplying an image.\\n\\nAs a stranger: *The noun changes* interests me where one painted surface has to carry two separate source relations; the outline lets the sentence turn at the base.\\n\\nThe next question: what can the surface color tell me about a repeated composition when the photographs were made under different conditions?\\n''')

with (root/'positions.md').open('a',encoding='utf-8') as f:
    f.write('''\\n\\nA museum description can attach different precedents to different parts of one object. Keep its relations separate even when the photograph makes them continuous.\\n''')
with (root/'practice.md').open('a',encoding='utf-8') as f:
    f.write('''\\n- When a collection description moves from a composition to its support, follow the noun and attach each relation to the part it actually names. This came from the Met's separate accounts of the Madonna group and the type of its base.\\n''')
with (root/'threads.md').open('a',encoding='utf-8') as f:
    f.write('''\\n- When a base type is related to architecture, what can the photograph establish about resemblance without proving descent?\\n''')

print('created project study and public page; linked from both project and public views')
