project=root/'projects/active/02-probably-after'
public=root/'public'

api_url='https://collectionapi.metmuseum.org/public/collection/v1/objects/190587'
req=urllib.request.Request(api_url,headers={'User-Agent':'Mozilla/5.0'})
with urllib.request.urlopen(req,context=ssl.create_default_context(cafile=certifi.where()),timeout=20) as response:
    api=json.load(response)
snapshot={
    'checked':'2026-10-11',
    'sourceApi':api_url,
    'objectID':api.get('objectID'),
    'title':api.get('title'),
    'artistDisplayName':api.get('artistDisplayName'),
    'objectDate':api.get('objectDate'),
    'medium':api.get('medium'),
    'objectURL':api.get('objectURL'),
    'primaryImage':api.get('primaryImage'),
    'additionalImages':api.get('additionalImages'),
}
(project/'references/190587-image-response-2026-10-11.json').write_text(json.dumps(snapshot,ensure_ascii=False,indent=2)+'\\n',encoding='utf-8')

