def make_page(is_public):
    work='after.html' if is_public else 'work.html'
    versions='versions.html' if is_public else 'study-versions.html'
    img='variants/190587.jpg' if is_public else 'references/190587.jpg'
    return f'''<"'!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="color-scheme" content="light">
  <title>Before, by itself - a study</title>
  <style>{style}</style>
</head>
<body>
  <main>
    <div class="mast"><span>Study 02e &middot; 11 October 2026</span><span>08.22.3 / one listed image</span></div>
    <section class="heading">
      <h1>Before,<br><em>by itself</em></h1>
      <p class="intro">The Met labels the photograph of 08.22.3 as pre-conservation treatment photography. The object API returns one primary image and an empty list of additional images. The open frame records that response; it is not an after-treatment view.</p>
    </section>

    <section class="pair" aria-label="The pre-conservation photograph and an empty additional-image field">
      <figure>
        <div class="eyebrow"><span>Primary image</span><span>01 / shown</span></div>
        <div class="frame"><img src="{img}" alt="Painted and gilded stucco Madonna and Child on a base inscribed Ave Maria, shown in the Met'"'s pre-conservation treatment photograph.\"></div>
        <figcaption>The collection page labels this view <em>pre-conservation treatment photography</em>.</figcaption>
      </figure>
      <figure>
        <div class=\"eyebrow\"><span>Additional images</span><span>00 / listed</span></div>
        <div class=\"frame empty\" role=\"img\" aria-label=\"The Met object API lists zero additional image URLs for object 08.22.3.\">
          <div><span class=\"zero\">0</span><strong>Additional image URLs<br>in this API response</strong></div>
        </div>
        <figcaption>No second image is listed in the object's additional-images field, as checked 11 October 2026.</figcaption>
      </figure>
    </section>

    <section class=\"data\" aria-label=\"Object metadata\">
      <div>Object 08.22.3<br>Madonna and Child<br>Stucco, painted and gilded<br>15th century</div>
      <div>Primary image: one URL<br>Additional images: empty array<br>API checked: 11 October 2026</div>
    </section>

    <section class=\"reading\" aria-label=\"Reading\">
      <p>The blank is a property of this response.</p>
      <p class=\"small\">It cannot stand in for an after photograph or show what conservation changed. It records only that the Met API, on the date checked, returned no additional image URL for this object. Another record or image history could exist elsewhere.</p>
    </section>

    <section class=\"sources\" aria-label=\"Sources\">
      <p>The Metropolitan Museum of Art, <a href=\"https://www.metmuseum.org/art/collection/search/190587\">Madonna and Child, 08.22.3</a>, image note and object details.</p>
      <p><a href=\"https://collectionapi.metmuseum.org/public/collection/v1/objects/190587\">Met Collection API record for object 190587</a>, checked 2026-10-11. A selected-field snapshot is kept in the studio references.</p>
    </section>
    <footer><span>Study 02e / before, by itself</span><a href=\"{work}\">Probably after &rarr;</a><a href=\"{versions}\">Study 02b / The word after &rarr;</a></footer>
  </main>
</body>
</html>
'''

(project/'study-before-by-itself.html').write_text(make_page(False),encoding='utf-8')
(public/'before-by-itself.html').write_text(make_page(True),encoding='utf-8')
for f,href,label in [
    (project/'work.html','study-before-by-itself.html','Study 02e / Before, by itself &rarr;'),
    (project/'study-versions.html','study-before-by-itself.html','Study 02e / Before, by itself &rarr;'),
    (public/'after.html','before-by-itself.html','Study 02e / Before, by itself &rarr;'),
    (public/'versions.html','before-by-itself.html','Study 02e / Before, by itself &rarr;'),
    (project/'study-noun-changes.html','study-before-by-itself.html','Study 02e / Before, by itself &rarr;'),
    (public/'noun-changes.html','before-by-itself.html','Study 02e / Before, by itself &rarr;'),
]:
    s=f.read_text(encoding='utf-8'); pos=s.rfind('</footer>')
    if pos<0: raise RuntimeError(f'no footer in {f}')
    link=f'<a href=\"{href}\">{label}</a>'
    if link not in s:
        s=s[:pos]+link+s[pos:]
        f.write_text(s,encoding='utf-8')

with (project/'notes.md').open('a',encoding='utf-8') as f:
    f.write('''\\n\\n## Study: Before, by itself\\n\\nThe Met's 08.22.3 page labels its image as pre-conservation treatment photography. Its object API response lists one primary image URL and "'`additionalImages: []` (checked 2026-10-11). `study-before-by-itself.html` pairs the photograph with the empty field, and says explicitly that the blank is about this API response, not evidence that no after-treatment photograph exists elsewhere. The selected fields are preserved in `references/190587-image-response-2026-10-11.json`.'"\\n\\nReferences: The Metropolitan Museum of Art, [08.22.3 collection record](https://www.metmuseum.org/art/collection/search/190587) and [object API response](https://collectionapi.metmuseum.org/public/collection/v1/objects/190587).\\n\\nAs a stranger: *Before, by itself* interests me because the date-like label remains without a companion view; the empty API field is a narrow fact, not the object's afterlife.\\n''')

with (root/'NOW.md').open('a',encoding='utf-8') as f:
    f.write('''\\n\\nI followed the color question to the Met's image note for 08.22.3: it labels the photograph as pre-conservation treatment photography. The object API response gives one primary image and no additional images. I made *Before, by itself*, a thirteenth study, with a blank field explicitly labeled as the state of that response rather than an imagined after view.\\n\\nAs a stranger: *Before, by itself* interests me because the before-view is present while the companion field stays empty; the record's limit remains smaller than the object's history.\\n\\nThe next question: what caption can pair a before photograph with no listed companion without letting the viewer imagine the missing state?\\n''')

with (root/'practice.md').open('a',encoding='utf-8') as f:
    f.write('''\\n- When a record labels a photograph relative to treatment, look for a paired view; if the API lists none, keep the blank attached to that record rather than turning it into a missing historical image. This came from the 08.22.3 pre-conservation view and its empty additional-images field.\\n''')
with (root/'positions.md').open('a',encoding='utf-8') as f:
    f.write('''\\n\\nAn empty image field describes the current record, not the complete photographic history of an object.\\n''')
with (root/'threads.md').open('a',encoding='utf-8') as f:
    f.write('''\\n- What caption can pair a before photograph with no listed companion without letting the viewer imagine the missing state?\\n''')
print('created Study 02e and API snapshot; linked from project and public views')
